const channels=[
  {name:'Meli',aliases:['Mercado Livre'],short:'ML',color:'#ffe600',ink:'#222',domain:'mercadolivre.com.br'},{name:'Shopee',short:'S',color:'#ee4d2d',domain:'shopee.com.br'},{name:'Amazon',short:'a',color:'#232f3e',domain:'amazon.com.br'},{name:'MagaLu',aliases:['Magazine Luiza'],short:'M',color:'#0086ff',domain:'magazineluiza.com.br'},{name:'Site',aliases:['Site Oficial'],short:'●',color:'#ff5a00',domain:'oficialwebshop.com.br'},{name:'TikTok',aliases:['TikTok Shop'],short:'♪',color:'#111',domain:'tiktok.com'},{name:'AliExpress',short:'AE',color:'#e62e04',domain:'aliexpress.com'},{name:'Via',aliases:['Casas Bahia'],short:'CB',color:'#1434a4',domain:'casasbahia.com.br'},{name:'WebContinental',short:'WC',color:'#0b3d78',domain:'webcontinental.com.br'},{name:'Madeira',short:'MM',color:'#ff6433',domain:'madeiramadeira.com.br'},{name:'Carrefour',short:'C',color:'#fff',ink:'#173d7a',domain:'carrefour.com.br'},{name:'Kabum',short:'K',color:'#ff6500',domain:'kabum.com.br'},{name:'Leroy',short:'LM',color:'#67a42f',domain:'leroymerlin.com.br'},{name:'Martins',short:'M',color:'#d71920',domain:'martinsatacado.com.br'}
];
const hours=['00h','02h','04h','06h','08h','10h','12h','14h','16h','18h','20h','22h'];
let data=[];
let activeChannel='all';
let liveMetrics={totalOrders:0,ticket:0};
let snapshotHistory=[],isUpdating=false;
let currentChannels={};
let previousChannels={};
let analyticData=[];
let rankingPage=0,lastRanking=[],lastRankingTotal=0;
const money=v=>'R$ '+new Intl.NumberFormat('pt-BR',{notation:v>=1e6?'compact':'standard',maximumFractionDigits:v>=1e6?2:0}).format(v);
const fullMoney=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
const iconFor=name=>channels.find(c=>[c.name,...(c.aliases||[])].some(a=>name.toLowerCase().includes(a.toLowerCase())))||{name,short:name.slice(0,2).toUpperCase(),color:'#444'};
const iconHtml=c=>c.domain?`<img src="https://www.google.com/s2/favicons?domain=${c.domain}&sz=64" alt="Logo ${c.name}" referrerpolicy="no-referrer">`:c.short;
function totals(){return data.map(d=>({...d,total:Number(currentChannels[d.channel]||0)})).filter(d=>d.total>0).sort((a,b)=>b.total-a.total)}
function renderEmpty(){const zero=money(0);document.querySelector('#totalGMV').textContent=zero;document.querySelector('#hourGMV').textContent=zero;document.querySelector('#currentHour').textContent='—';document.querySelector('#totalDelta').textContent='Aguardando primeira carga';document.querySelector('#hourDelta').textContent='Sem snapshot registrado';document.querySelector('#leaderName').textContent='Aguardando vendas';document.querySelector('#leaderShare').textContent='0% do GMV';document.querySelector('#leaderIcon').innerHTML='—';document.querySelector('#leaderProgress').style.width='0';document.querySelector('#targetValue').textContent='0.0%';document.querySelector('#targetProgress').style.width='0';document.querySelector('#targetGap').textContent='Aguardando primeira carga do dia';['ordersKpi','activeKpi'].forEach(id=>document.querySelector('#'+id).textContent='0');document.querySelector('#ticketKpi').textContent=zero;document.querySelector('#activeLabel').textContent='Nenhum canal carregado';document.querySelector('#top3Kpi').textContent='0.0%';document.querySelector('#paceKpi').textContent='Aguardando';document.querySelector('#paceLabel').textContent='Sem histórico horário';document.querySelector('#rankingPage').textContent='0 CANAIS ATIVOS';document.querySelector('#ranking').innerHTML='<div class="empty-state">A primeira carga de hoje ainda não foi disponibilizada.</div>';document.querySelector('#tickerTrack').innerHTML='<span>AGUARDANDO PRIMEIRA CARGA DO DIA</span>';document.querySelector('#insightText').textContent='O painel começará a registrar o histórico a partir da primeira atualização com dados.';document.querySelector('#chartTitle').textContent='GMV HORA A HORA';document.querySelector('#chartLegend').innerHTML='<i class="orange"></i> Aguardando primeiro snapshot';document.querySelector('#axis').innerHTML=[0,0,0,0,0].map(money).map(v=>`<span>${v}</span>`).join('');document.querySelector('#hourlyChart').innerHTML=['08h','09h','10h','11h','12h','13h','14h','15h','16h','17h','18h','19h','20h','21h','22h','23h'].map(h=>`<div class="bar-group"><div class="bar" style="height:2px"></div><label>${h}</label></div>`).join('');document.querySelector('#peakLabel').textContent='Nenhuma venda carregada';document.querySelector('#sparkline').innerHTML='';lastRanking=[];lastRankingTotal=0}
function render(){
  if(!data.length)return renderEmpty();
  const ranked=totals(),total=Number(liveMetrics.totalGmv||ranked.reduce((s,d)=>s+d.total,0)),lastIdx=Math.max(...data.map(d=>d.hours.length))-1;
  const confirmed=snapshotHistory.filter(x=>!x.isBaseline),hourTotal=Number(confirmed.at(-1)?.deltaGmv||0),previousAccum=total-hourTotal,delta=previousAccum?(hourTotal/previousAccum)*100:0,hasComparison=confirmed.length>0;
  document.querySelector('#totalGMV').textContent=money(total);document.querySelector('#hourGMV').textContent=money(hourTotal);document.querySelector('#currentHour').textContent=data[0]?.hours[lastIdx]?.hour||'—';
  document.querySelector('#hourDelta').textContent=hasComparison?`▲ ${delta.toFixed(1)}% sobre acumulado anterior`:'Aguardando próxima janela';document.querySelector('#hourDelta').style.color=hasComparison?'var(--green)':'var(--muted)';
  const accDelta=delta;document.querySelector('#totalDelta').textContent=`▲ ${accDelta.toFixed(1)}% na janela atual`;
  document.querySelector('#hourProgress').style.width=Math.min(100,hourTotal/300000*100)+'%';
  const leader=ranked[0],li=iconFor(leader.channel);document.querySelector('#leaderName').textContent=leader.channel;document.querySelector('#leaderShare').textContent=`${(leader.total/total*100).toFixed(1)}% do GMV`;
  Object.assign(document.querySelector('#leaderIcon').style,{background:li.color,color:li.ink||'#fff'});document.querySelector('#leaderIcon').innerHTML=iconHtml(li);document.querySelector('#leaderProgress').style.width=(leader.total/total*100)+'%';
  const target=671585,pct=total/target*100;document.querySelector('#targetValue').textContent=pct.toFixed(1)+'%';document.querySelector('#targetProgress').style.width=Math.min(100,pct)+'%';document.querySelector('#targetGap').textContent=total>=target?`Meta superada em ${money(total-target)}`:`Faltam ${money(target-total)} para a meta`;
  const top3=ranked.slice(0,3).reduce((s,d)=>s+d.total,0);document.querySelector('#ordersKpi').textContent=new Intl.NumberFormat('pt-BR').format(liveMetrics.totalOrders||0);document.querySelector('#ticketKpi').textContent=money(liveMetrics.ticket||0);document.querySelector('#activeKpi').textContent=ranked.filter(d=>d.total>0).length;document.querySelector('#activeLabel').textContent=`${ranked.filter(d=>d.total>0).length} canais com venda`;document.querySelector('#top3Kpi').textContent=(total?top3/total*100:0).toFixed(1)+'%';document.querySelector('#paceKpi').textContent=!hasComparison?'Monitorando':delta>5?'Acelerando':'Estável';document.querySelector('#paceKpi').style.color=delta>5?'var(--green)':'#fff';document.querySelector('#paceLabel').textContent=hasComparison?`+${delta.toFixed(1)}% na janela atual`:'Aguardando próximo snapshot';document.querySelector('#insightText').textContent=`${leader.channel} lidera com ${(leader.total/total*100).toFixed(1)}% do GMV; Top 3 concentram ${(top3/total*100).toFixed(1)}% das vendas.`;
  lastRanking=ranked;lastRankingTotal=total;rankingPage=Math.min(rankingPage,Math.max(0,Math.ceil(ranked.length/8)-1));renderRanking(ranked,total);renderTicker(ranked);renderChart();renderSpark();
}
function renderRanking(ranked,total){const max=ranked[0]?.total||1,container=document.querySelector('#ranking');document.querySelector('#rankingPage').textContent=`${ranked.length} CANAIS ATIVOS`;container.className='ranking '+(ranked.length>10?'dense':'');container.innerHTML=ranked.map((d,i)=>{const c=iconFor(d.channel),previous=Number(previousChannels[d.channel]||0),change=previous?(d.total/previous-1)*100:d.total>0?100:0,medal=i===0?'🥇':i===1?'🥈':i===2?'🥉':String(i+1).padStart(2,'0');return `<div class="rank-row ${i<3?'podium rank-'+(i+1):''}"><div class="place">${medal}</div><div class="channel-icon" style="background:${c.color};color:${c.ink||'#fff'}">${iconHtml(c)}</div><div class="channel-name"><strong>${d.channel}</strong><small>${(d.total/total*100).toFixed(1)}% participação</small></div><div class="rank-bar"><i style="width:${d.total/max*100}%"></i></div><div class="gmv"><strong>${money(d.total)}</strong><small style="color:${change>=0?'var(--green)':'#ff6262'}">${change>=0?'▲':'▼'} ${Math.abs(change).toFixed(1)}%</small></div></div>`}).join('')}
function renderTicker(ranked){const content=ranked.map((d,i)=>`<span><b>#${i+1}</b> ${d.channel} <strong>${money(d.total)}</strong></span>`).join('<i>◆</i>');document.querySelector('#tickerTrack').innerHTML=content+content}
function renderChart(){
  const history=snapshotHistory;
  document.querySelector('#chartTitle').textContent='GMV POR ATUALIZAÇÃO (30 MIN)';
  document.querySelector('#chartLegend').innerHTML=isUpdating?'<i class="orange"></i> Nova janela em processamento':'<i class="orange"></i> Incrementos confirmados';
  if(!history.length){document.querySelector('#axis').innerHTML=[0,0,0,0,0].map(money).map(v=>`<span>${v}</span>`).join('');document.querySelector('#hourlyChart').innerHTML='';document.querySelector('#peakLabel').textContent='Nenhum snapshot registrado';return}
  let points=history.map((s,i)=>({label:s.slot,value:i===0?Number(s.gmv||0):Number(s.deltaGmv||0),baseline:i===0,total:s.gmv}));
  if(activeChannel!=='all'){
    const row=data.find(d=>d.channel===activeChannel);
    points=(row?.hours||[]).map((h,i)=>({label:h.hour,value:Number(h.value||0),baseline:i===0,total:i===0?Number(h.value||0):null}));
  }
  const rawMax=Math.max(...points.map(p=>p.value),1),target=rawMax*1.18,magnitude=10**Math.floor(Math.log10(target)),normalized=target/magnitude;
  const scale=[1,2,2.5,5,10].find(step=>normalized<=step)*magnitude;
  document.querySelector('#axis').innerHTML=[scale,scale*.75,scale*.5,scale*.25,0].map(money).map(v=>`<span>${v}</span>`).join('');
  document.querySelector('#hourlyChart').innerHTML=points.map((p,i)=>`<div class="bar-group ${i===points.length-1?'latest':''}"><div class="bar ${p.baseline?'projected':''}" style="height:${Math.max(2,p.value/scale*100)}%" data-value="${p.baseline?'Carga inicial: '+fullMoney(p.value):fullMoney(p.value)}"></div><label>${p.label}</label></div>`).join('');
  const realized=points.filter(p=>!p.baseline),peak=realized.reduce((best,p)=>!best||p.value>best.value?p:best,null);
  document.querySelector('#peakLabel').textContent=peak?`Maior incremento: ${peak.label} • ${money(peak.value)}`:`Carga inicial registrada às ${points[0].label}; aguardando próximo intervalo`;
}
function renderSpark(){let vals=hours.map((_,i)=>data.reduce((s,d)=>s+(d.hours[i]?.value||0),0)),max=Math.max(...vals),min=Math.min(...vals),pts=vals.map((v,i)=>`${i/(vals.length-1)*116},${36-(v-min)/(max-min||1)*32}`).join(' ');document.querySelector('#sparkline').innerHTML=`<svg viewBox="0 0 118 38"><polyline points="${pts}" fill="none" stroke="#ff6410" stroke-width="2"/><polyline points="0,38 ${pts} 118,38" fill="#ff5a0015" stroke="none"/></svg>`}
function stamp(){document.querySelector('#lastUpdate').textContent=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date())}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
function renderAnalytics(){const q=document.querySelector('#analyticSearch').value.trim().toLowerCase(),company=document.querySelector('#analyticCompany').value,canal=document.querySelector('#analyticChannel').value,filtered=analyticData.filter(x=>(company==='all'||x.empresa===company)&&(canal==='all'||x.canal===canal)&&(!q||[x.pedido,x.empresa,x.canal,x.ecommerce,x.situacao].some(v=>String(v).toLowerCase().includes(q))));document.querySelector('#analyticOrders').textContent=new Intl.NumberFormat('pt-BR').format(analyticData.length);document.querySelector('#analyticGmv').textContent=money(analyticData.reduce((s,x)=>s+(+x.valor||0),0));document.querySelector('#analyticComplete').textContent=(analyticData.length?analyticData.filter(x=>x.detalhe==='Completo').length/analyticData.length*100:0).toFixed(0)+'%';document.querySelector('#analyticsRows').innerHTML=filtered.length?filtered.map(x=>`<tr><td><b>${x.pedido}</b></td><td>${x.empresa}</td><td><span class="channel-pill">${x.canal}</span></td><td>${x.ecommerce}</td><td>${x.situacao}</td><td class="${x.detalhe==='Completo'?'detail-complete':'detail-pending'}">${x.detalhe}</td><td>${fullMoney(x.valor)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty-table">Nenhum pedido encontrado com os filtros selecionados.</td></tr>'}
function setupAnalytics(payload){analyticData=payload.analytics||[];const options=[...new Set(analyticData.map(x=>x.canal))].sort();document.querySelector('#analyticChannel').innerHTML='<option value="all">Todos os canais</option>'+options.map(x=>`<option>${x}</option>`).join('');renderAnalytics()}
async function loadBigQuery(update=false){const endpoint=update?'/api/update-data':'/api/data';try{const response=await fetch(endpoint,{cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Falha na atualização');const payload=await response.json();isUpdating=Boolean(payload.updating);document.querySelector('#updateStatus').classList.toggle('syncing',isUpdating);document.querySelector('#statusLabel').textContent=isUpdating?'ATUALIZANDO NOVA JANELA':'ÚLTIMA ATUALIZAÇÃO';setupAnalytics(payload);snapshotHistory=payload.snapshotHistory||[];currentChannels=payload.currentChannels||{};previousChannels=payload.previousChannels||{};if(payload.series?.length){data=payload.series;liveMetrics=payload.metrics||liveMetrics;hours.splice(0,hours.length,...data[0].hours.map(h=>h.hour));document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>'+data.map(d=>`<option>${d.channel}</option>`).join('');render();if(payload.updatedAt)document.querySelector('#lastUpdate').textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(payload.updatedAt));return true}data=[];liveMetrics={totalOrders:0,ticket:0};currentChannels={};previousChannels={};document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>';renderEmpty();if(update&&payload.waitingForLoad)toast('A primeira carga de hoje ainda não saiu');return true}catch(error){if(update)toast('Tiny: '+error.message);return false}}
document.querySelector('#refreshBtn').addEventListener('click',async e=>{e.currentTarget.classList.add('loading');const ok=await loadBigQuery(true);e.currentTarget.classList.remove('loading');if(ok)toast('Tiny atualizado e snapshot registrado')});
document.querySelector('#channelFilter').innerHTML+=[...channels].map(c=>`<option>${c.name}</option>`).join('');document.querySelector('#channelFilter').addEventListener('change',e=>{activeChannel=e.target.value==='all'?'all':e.target.value;renderChart()});
document.querySelectorAll('.view-tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.view-tab,.report-view').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.querySelector('#'+button.dataset.view).classList.add('active')}));document.querySelector('#analyticSearch').addEventListener('input',renderAnalytics);document.querySelector('#analyticCompany').addEventListener('change',renderAnalytics);document.querySelector('#analyticChannel').addEventListener('change',renderAnalytics);
document.querySelector('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text(),lines=text.trim().split(/\r?\n/),sep=lines[0].includes(';')?';':',',head=lines.shift().split(sep).map(x=>x.trim().toLowerCase()),ci=head.findIndex(x=>['canal','channel'].includes(x)),hi=head.findIndex(x=>['hora','hour'].includes(x)),vi=head.findIndex(x=>['gmv','valor','value'].includes(x));if([ci,hi,vi].some(x=>x<0))throw Error();const map={};lines.forEach(l=>{const p=l.split(sep),name=p[ci].trim(),hour=p[hi].trim(),value=Number(p[vi].replace(/[^0-9,.-]/g,'').replace('.','').replace(',','.'));if(!map[name])map[name]={};map[name][hour]= (map[name][hour]||0)+value});const newHours=[...new Set(lines.map(l=>l.split(sep)[hi].trim()))];hours.splice(0,hours.length,...newHours);data=Object.entries(map).map(([channel,obj])=>({channel,hours:newHours.map(hour=>({hour,value:obj[hour]||0}))}));activeChannel='all';document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>'+data.map(d=>`<option>${d.channel}</option>`).join('');render();stamp();toast(`${data.length} canais importados com sucesso`)}catch{toast('CSV inválido. Use as colunas: hora, canal, gmv')}});
setInterval(()=>{const e=document.querySelector('#liveClock');if(e)e.textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date())},1000);setInterval(()=>loadBigQuery(false),15000);stamp();render();loadBigQuery(false);
